int send_ocsp_request(const char *server,
        gnutls_x509_crt_t cert, gnutls_x509_crt_t issuer,
        gnutls_datum_t * resp_data, gnutls_datum_t *nonce)
{
 gnutls_datum_t ud;
 int ret;
 gnutls_datum_t req;
 char *url = (void *) server;
 char headers[1024];
 char service[16];
 unsigned char *p;
 const char *hostname;
 const char *path = "";
 unsigned i;
 unsigned int headers_size = 0, port;
 socket_st hd;

 sockets_init();

 if (url == 
           ((void *)0)
               ) {

  gnutls_datum_t data;

  i = 0;
  do {
   ret = gnutls_x509_crt_get_authority_info_access(cert, i++,
         GNUTLS_IA_OCSP_URI,
         &data,

        ((void *)0)
            );
  } while(ret == -105);

  if (ret < 0) {
   i = 0;
   do {
    ret =
        gnutls_x509_crt_get_authority_info_access
        (issuer, i++, GNUTLS_IA_OCSP_URI, &data, 
                                                ((void *)0)
                                                    );
   } while(ret == -105);
  }

  if (ret < 0) {
   fprintf(
          stderr
                ,
    "*** Cannot find OCSP server URI in certificate: %s\n",
    gnutls_strerror(ret));
   return ret;
  }

  url = malloc(data.size + 1);
  if (url == 
            ((void *)0)
                ) {
      return -1;
  }
  memcpy(url, data.data, data.size);
  url[data.size] = 0;

  gnutls_free((void *) (data.data)), data.data=
 ((void *)0)
                       ;
 }

 hostname = host_from_url(url, &port, &path);
 if (port != 0)
  snprintf(service, sizeof(service), "%u", port);
 else
  strcpy(service, "80");

 fprintf(
        stderr
              , "Connecting to OCSP server: %s...\n", hostname);

 memset(&ud, 0, sizeof(ud));

 _generate_request(cert, issuer, &req, nonce);

 snprintf(headers, sizeof(headers), "POST /%s HTTP/1.0\r\n" "Host: %s\r\n" "Accept: */*\r\n" "Content-Type: application/ocsp-request\r\n" "Content-Length: %u\r\n" "Connection: close\r\n\r\n", path, hostname,
   (unsigned int) req.size);
 headers_size = strlen(headers);

 socket_open2(&hd, hostname, service, 
((void *)0)
, (1<<3)|(1<<5), "Connecting to", 
((void *)0)
, 
((void *)0)
, 
((void *)0)
, 
((void *)0)
);

 socket_send(&hd, headers, headers_size);
 socket_send(&hd, req.data, req.size);
 gnutls_free((void *) (req.data)), req.data=
((void *)0)
                     ;

 do {
  ret = socket_recv(&hd, buffer, sizeof(buffer));
  if (ret > 0)
   get_data(buffer, ret, 1, &ud);
 } while (ret > 0);

 if (ret < 0 || ud.size == 0) {
  perror("recv");
  ret = -1;
  goto cleanup;
 }

 socket_bye(&hd, 0);

 p = memmem(ud.data, ud.size, "\r\n\r\n", 4);
 if (p == 
         ((void *)0)
             ) {
  fprintf(
         stderr
               , "Cannot interpret HTTP response\n");
  ret = -1;
  goto cleanup;
 }

 p += 4;
 resp_data->size = ud.size - (p - ud.data);
 resp_data->data = malloc(resp_data->size);
 if (resp_data->data == 
                       ((void *)0)
                           ) {
  perror("recv");
  ret = -1;
  goto cleanup;
 }

 memcpy(resp_data->data, p, resp_data->size);

 ret = 0;

 cleanup:
 free(ud.data);
 if (url != server)
  free(url);

 return ret;
}

