 char name[256];
 int cert_set = 0;
 unsigned use_static_dh_params = 0;
 unsigned i;

 cmd_parser(argc, argv);


 signal(
       1
             , 
               ((__sighandler_t) 1)
                      );
 signal(
       15
              , terminate);
 if (signal(
           2
                 , terminate) == 
                                 ((__sighandler_t) 1)
                                        )
  signal(
        2
              , 
                ((__sighandler_t) 1)
                       );


 sockets_init();

 listener_list = gl_list_create_empty(&gl_linked_list_implementation,

         ((void *)0)
             , 
               ((void *)0)
                   , listener_free,

         1
             );

 if (nodb == 0)
  wrap_db_init();

