void
socket_open2(socket_st * hd, const char *hostname, const char *service,
     const char *app_proto, int flags, const char *msg, gnutls_datum_t *rdata, gnutls_datum_t *edata,
     FILE *server_trace, FILE *client_trace)
{
 struct addrinfo hints, *res, *ptr;
 int sd, err = 0;
 int udp = flags & 1;
 int ret;
 int fastopen = flags & (1<<1);
 char buffer[4096 + 1];
 char portname[16] = { 0 };
 gnutls_datum_t idna;
 char *a_hostname;

 memset(hd, 0, sizeof(*hd));

 if (flags & (1<<4))
  hd->verbose = 1;

 if (rdata) {
  hd->rdata.data = rdata->data;
  hd->rdata.size = rdata->size;
 }

 if (edata) {
  hd->edata.data = edata->data;
  hd->edata.size = edata->size;
 }

 ret = gnutls_idna_map(hostname, strlen(hostname), &idna, 0);
 if (ret < 0) {
  fprintf(
         stderr
               , "Cannot convert %s to IDNA: %s\n", hostname, gnutls_strerror(ret));
  exit(1);
 }

 hd->hostname = strdup(hostname);
 a_hostname = (char*)idna.data;

 if (msg != 
           ((void *)0)
               )
  log_msg(
         stdout
               , "Resolving '%s:%s'...\n", a_hostname, service);


 memset(&hints, 0, sizeof(hints));
 hints.ai_socktype = udp ? 
                          SOCK_DGRAM 
                                     : 
                                       SOCK_STREAM
                                                  ;
 if ((err = getaddrinfo(a_hostname, service, &hints, &res))) {
  fprintf(
         stderr
               , "Cannot resolve %s:%s: %s\n", hostname,
   service, gai_strerror(err));
  exit(1);
 }

 sd = -1;
 for (ptr = res; ptr != 
                       ((void *)0)
                           ; ptr = ptr->ai_next) {
  sd = socket(ptr->ai_family, ptr->ai_socktype,
       ptr->ai_protocol);
  if (sd == -1)
   continue;

  if ((err =
       getnameinfo(ptr->ai_addr, ptr->ai_addrlen, buffer,
     4096, portname, sizeof(portname),

    1 
                   | 
                     2
                                   )) != 0) {
   fprintf(
          stderr
                , "getnameinfo(): %s\n",
    gai_strerror(err));
   close(sd);
   continue;
  }

  if (hints.ai_socktype == 
                          SOCK_DGRAM
                                    ) {







   int yes = 
            2
                          ;
   if (setsockopt(sd, 
                     IPPROTO_IP
                               , 
                                 10
                                                ,
           (const void *) &yes,
           sizeof(yes)) < 0)
    perror("setsockopt(IP_DF) failed");

  }

  if (fastopen && ptr->ai_socktype == 
                                     SOCK_STREAM

     && (ptr->ai_family == 
                           2 
                                   || ptr->ai_family == 
                                                        10
                                                                )) {
   memcpy(&hd->connect_addr, ptr->ai_addr, ptr->ai_addrlen);
   hd->connect_addrlen = ptr->ai_addrlen;

   if (msg)
    log_msg(
           stdout
                 , "%s '%s:%s' (TFO)...\n", msg, buffer, portname);

  } else {
   if (msg)
    log_msg(
           stdout
                 , "%s '%s:%s'...\n", msg, buffer, portname);

   if ((err = connect(sd, ptr->ai_addr, ptr->ai_addrlen)) < 0) {
    close(sd);
    continue;
   }
  }

  hd->fd = sd;
  if (flags & (1<<2)) {
   hd->app_proto = app_proto;
   socket_starttls(hd);
   hd->app_proto = 
                  ((void *)0)
                      ;
  }

  if (!(flags & (1<<5))) {
   hd->session = init_tls_session(hostname);
   if (hd->session == 
                     ((void *)0)
                         ) {
    fprintf(
           stderr
                 , "error initializing session\n");
    close(sd);
    exit(1);
   }
  }

  if (hd->session) {
   if (hd->edata.data) {
    ret = gnutls_record_send_early_data(hd->session, hd->edata.data, hd->edata.size);
    if (ret < 0) {
     fprintf(
            stderr
                  , "error sending early data\n");
     close(sd);
     exit(1);
    }
   }
   if (hd->rdata.data) {
    gnutls_session_set_data(hd->session, hd->rdata.data, hd->rdata.size);
   }

   if (client_trace || server_trace) {
    hd->server_trace = server_trace;
    hd->client_trace = client_trace;
    gnutls_transport_set_push_function(hd->session, wrap_push);
    gnutls_transport_set_pull_function(hd->session, wrap_pull);
    gnutls_transport_set_pull_timeout_function(hd->session, wrap_pull_timeout_func);
    gnutls_transport_set_ptr(hd->session, hd);
   } else {
    gnutls_transport_set_int2(hd->session, hd->fd, hd->fd);
   }
  }

  if (!(flags & (1<<3)) && !(flags & (1<<5))) {
   err = do_handshake(hd);
   if (err == -53) {
    gnutls_deinit(hd->session);
    hd->session = 
                 ((void *)0)
                     ;
    close(sd);
    continue;
   }
   else if (err < 0) {
    if (!(flags & (1<<6)))
     fprintf(
            stderr
                  , "*** handshake has failed: %s\n", gnutls_strerror(err));
    close(sd);
    exit(1);
   }
  }

  break;
 }

 if (err != 0) {
  int e = 
         (*__errno_location ())
              ;
  fprintf(
         stderr
               , "Could not connect to %s:%s: %s\n",
    buffer, portname, strerror(e));
  exit(1);
 }

 if (sd == -1) {
  fprintf(
         stderr
               , "Could not find a supported socket\n");
  exit(1);
 }

 if ((flags & (1<<3)) || (flags & (1<<5)))
  hd->secure = 0;
 else
  hd->secure = 1;

 hd->fd = sd;
 hd->ip = strdup(buffer);
 hd->service = strdup(portname);
 hd->ptr = ptr;
 hd->addr_info = res;
 gnutls_free((void *) (hd->rdata.data)), hd->rdata.data=
((void *)0)
                           ;
 hd->rdata.data = 
                 ((void *)0)
                     ;
 gnutls_free((void *) (hd->edata.data)), hd->edata.data=
((void *)0)
                           ;
 hd->edata.data = 
                 ((void *)0)
                     ;
 gnutls_free((void *) (idna.data)), idna.data=
((void *)0)
                      ;
 return;
}

