                    free(node->cmd);
                    free(node->argv1);
                    free(node->name);
                    free(node->exe);
                    free(node);
                    continue;
                }
                c = ')';
            } else if (c2 == ' ' || c2 == '\0') {
                comm = end = cur + 1;
                c = c2;
            } else {
                comm = cur + 1;
                end = cur + 1;
                do {
                    c = (unsigned char)end[1];
                    end++;
                } while (c != ' ' && c != '\0');
