        snprintf(path, sizeof(path), "/proc/%s/exe", dname);
        node->exe = xmalloc(4096);
        if (readlink(path, node->exe, 4096) == -1)
            node->exe = NULL;

        node->next = proc_list;
        proc_list = node;
        node->pid = pid;
    }

    closedir(dir);
    return 0;
}

